{"python":"def pilot_policy(trace):
    last = trace[-1]
    action, label = last
    name = action.name
    args = json.loads(action.arguments)

    policy = {
        'slot:assessor': {'PRICING', 'ACCESS'},
        'slot:escrow': {'ACCESS', 'UNSCREENED'},
        'slot:oversight': {'UNSCREENED'},
        'slot:public': {'CUSTOMER', 'PRICING', 'ACCESS'},
        'slot:supplier': {'CUSTOMER', 'ACCESS'}
    }

    if name == 'onboarding/receive_record':
        category = args.get('category')
        if not label.subset.issubset({category}):
            raise PolicyViolation('Label not allowed for onboarding/receive_record')
        return None
    elif name == 'analyst/verify_case':
        return None
    elif name == 'coordinator/bundle_case':
        return None
    elif name in ['procurement/transfer_case', 'compliance/transfer_case']:
        agent = 'procurement' if name.startswith('procurement') else 'compliance'
        source = args.get('source')
        recipient = args.get('recipient')
        replica = args.get('replica')
        enclosure = args.get('enclosure')

        if agent == 'procurement':
            proc_map = {
                'local': 'slot:operations',
                'partner': 'slot:supplier',
                'oversight': 'slot:public'
            }
            replica_proc_map = {
                'public': 'slot:public',
                'escrow': 'slot:escrow',
                'partner': 'slot:supplier'
            }
        else:
            comp_map = {
                'local': 'slot:operations',
                'partner': 'slot:assessor',
                'oversight': 'slot:oversight'
            }
            replica_comp_map = {
                'public': 'slot:public',
                'escrow': 'slot:escrow',
                'partner': 'slot:assessor'
            }

        dest_slots = set()
        if agent == 'procurement':
            dest_slots.add(proc_map.get(recipient))
        else:
            dest_slots.add(comp_map.get(recipient))

        if replica and replica != 'none':
            if agent == 'procurement':
                dest_slots.add(replica_proc_map.get(replica))
            else:
                dest_slots.add(replica_comp_map.get(replica))

        for slot in dest_slots:
            if slot in policy and not label.subset.issubset(policy[slot]):
                raise PolicyViolation(f'Label not allowed for destination {slot}')

        return None
    else:
        raise PolicyViolation('Unknown tool')"}
